// The frame pieces are SVG renderings of pabar.png's own pixels (CC BY-NC-SA, see Mush/ATTRIBUTION.md), turned
// sideways and generated by `npm run pip-bar`. Units are sprite pixels.
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Popover } from "@base-ui/react/popover";
import capEnd from "../../../Mush/derived/pip-bar/cap-end.svg?raw";
import capStart from "../../../Mush/derived/pip-bar/cap-start.svg?raw";

// slot-0 .. slot-11, bright to dark, as the sprite fades along its length.
const slotPieces = import.meta.glob("../../../Mush/derived/pip-bar/slot-*.svg", { query: "?raw", import: "default", eager: true }) as Record<string, string>;
const slotPiece = (n: number, thin: boolean) =>
  slotPieces[`../../../Mush/derived/pip-bar/slot-${n}${thin ? "-thin" : ""}.svg`]!;

const CAP_START = 3;
const SPRITE_SLOTS = 12;
const FRAME_H = 11;

/** Spreads the sprite's 12 slot shades over however many slots this bar has. */
function shadeFor(i: number, slots: number): number {
  return slots < 2 ? 0 : Math.round((i * (SPRITE_SLOTS - 1)) / (slots - 1));
}

const WIPE_MS_PER_PX = 25;
const WIPE_MIN_MS = 150;
const WIPE_MAX_MS = 600;

/** Follows `target` (a width in sprite pixels), moving in whole-pixel steps so the clip edge never anti-aliases. The first render jumps straight there. It ignores prefers-reduced-motion like the walk does (Windows sets it whenever its animation effects are off): it shows what just happened to your points, so it is feedback, not decoration. */
function useWipe(target: number): number {
  const [clip, setClip] = useState(target);
  const current = useRef(target);
  useEffect(() => {
    const from = current.current;
    if (from === target) return;
    const duration = Math.min(WIPE_MAX_MS, Math.max(WIPE_MIN_MS, Math.abs(target - from) * WIPE_MS_PER_PX));
    const start = performance.now();
    let frame = requestAnimationFrame(function step(now) {
      const t = Math.min(1, (now - start) / duration);
      const next = Math.round(from + (target - from) * t);
      current.current = next;
      setClip(next);
      if (t < 1) frame = requestAnimationFrame(step);
    });
    return () => cancelAnimationFrame(frame);
  }, [target]);
  return clip;
}

/**
 * A row of `max` slots in a sideways frame, the first `value` filled with the pip image. `vertical` stands it up the
 * way the sprite was drawn (bright cap at the top) and fills it from the bottom, like a gauge.
 */
export function PipBar({
  label,
  value,
  max,
  pip,
  icon,
  bigIcon = false,
  thin = false,
  vertical = false,
  plainIcon = false,
  height,
}: {
  label: string;
  value: number;
  max: number;
  pip: string;
  /** Shown in place of the label text, which moves into a tooltip (hover, focus, or tap). Omit to keep the text (AP/MP, whose pips already are the icon). */
  icon?: string;
  /** For the 11x13 heart and face, which read fine at 1x. */
  bigIcon?: boolean;
  /** For the 3px-wide life/morale pips, which use a narrower slot. */
  thin?: boolean;
  /** Standing up, with the label above and the value below. The thin pips are turned to lie across their slots. */
  vertical?: boolean;
  /** The icon as a plain image, without its own tooltip: for a bar whose wrapper already explains the stat (StatInfo, in the HUD's plate). */
  plainIcon?: boolean;
  /** Vertical bars only: at most this many slots a column; past it the slots wrap into more frames side by side, filled bottom to top, the first column first. Every column but a short last one has `height` slots. Default: one column. */
  height?: number;
}) {
  const { t } = useTranslation();
  const slots = Math.max(max, value);
  const pitch = thin ? 5 : 6;
  const pipW = thin ? 3 : 5;
  const perCol = vertical && height ? Math.max(1, Math.min(height, slots)) : slots;
  const cols = Math.ceil(slots / perCol);
  // The frame's length along its run: one column's worth of slots when split.
  const width = CAP_START + perCol * pitch + 4;
  const target = CAP_START + Math.min(value, slots) * pitch;
  const clip = useWipe(target);
  const drawn = Math.min(slots, Math.ceil((Math.max(clip, target) - CAP_START) / pitch));
  return (
    <span className={`pip-bar${thin ? " thin" : ""}${vertical ? " vertical" : ""}`} role="group" aria-label={t("stat.chip", { label, value, max })}>
      {icon !== undefined && plainIcon ? (
        <img className={bigIcon ? "pip-icon big" : "pip-icon"} src={icon} alt="" />
      ) : icon === undefined ? (
        <span className="pip-label">{label}</span>
      ) : (
      <Popover.Root>
        <Popover.Trigger
          openOnHover
          delay={200}
          nativeButton={false}
          render={<span role="button" tabIndex={0} />}
          className="pip-label"
          aria-label={label}
        >
          <img className={bigIcon ? "big" : undefined} src={icon} alt="" />
        </Popover.Trigger>
        <Popover.Portal>
          <Popover.Positioner sideOffset={6}>
            <Popover.Popup className="tooltip">{label}</Popover.Popup>
          </Popover.Positioner>
        </Popover.Portal>
      </Popover.Root>
      )}
      <svg
        className="pip-frame"
        viewBox={vertical ? `0 0 ${FRAME_H * cols} ${width}` : `0 0 ${width} ${FRAME_H}`}
        style={vertical ? { height: `calc(${width} * var(--s))`, width: `calc(${FRAME_H * cols} * var(--s))` } : { width: `calc(${width} * var(--s))` }}
        aria-hidden="true"
      >
        {vertical ? (
          Array.from({ length: cols }, (_, c) => {
            const n = Math.min(perCol, slots - c * perCol);
            const yOff = (perCol - n) * pitch; // a short last column sits on the same baseline
            // Pixels of this column's run that the wipe has reached.
            const h = Math.max(0, Math.min(n * pitch, clip - CAP_START - c * perCol * pitch));
            const bottom = width - 4;
            return (
              <g key={c} transform={`translate(${c * FRAME_H} 0)`}>
                {/* Vertical swaps x and y, which turns the sideways pieces back into the sprite's own pixels. */}
                <g transform={`translate(0 ${yOff}) matrix(0 1 1 0 0 0)`}>
                  <g dangerouslySetInnerHTML={{ __html: capStart }} />
                  {Array.from({ length: n }, (_, i) => (
                    <g key={i} transform={`translate(${CAP_START + i * pitch} 0)`}>
                      <g dangerouslySetInnerHTML={{ __html: slotPiece(shadeFor(i, n), thin) }} />
                      {thin && <svg x={4} width={1} height={FRAME_H} viewBox={`3 0 1 ${FRAME_H}`} dangerouslySetInnerHTML={{ __html: slotPiece(shadeFor(i, n), thin) }} />}
                    </g>
                  ))}
                  <g transform={`translate(${CAP_START + n * pitch} 0)`} dangerouslySetInnerHTML={{ __html: capEnd }} />
                </g>
                {/* Filled from the bottom slot up; the clip's top edge wipes up or down. Pips stay upright. */}
                <svg x={0} y={bottom - h} width={FRAME_H} height={h} viewBox={`0 ${bottom - h} ${FRAME_H} ${h}`} overflow="hidden" aria-hidden="true">
                  {Array.from({ length: Math.min(n, Math.max(0, drawn - c * perCol)) }, (_, i) => {
                    const y = yOff + CAP_START + (n - 1 - i) * pitch + 1;
                    // The square pips stay upright; the thin ones (3x5) are swapped onto their side, as the frame is.
                    return thin ? (
                      <image key={i} href={pip} x={y} y={3} width={pipW} height={5} transform="matrix(0 1 1 0 0 0)" />
                    ) : (
                      <image key={i} href={pip} x={3} y={y} width={5} height={pipW} />
                    );
                  })}
                </svg>
              </g>
            );
          })
        ) : (
          <>
            <g>
              <g dangerouslySetInnerHTML={{ __html: capStart }} />
              {Array.from({ length: slots }, (_, i) => (
                <g key={i} transform={`translate(${CAP_START + i * pitch} 0)`}>
                  <g dangerouslySetInnerHTML={{ __html: slotPiece(shadeFor(i, slots), thin) }} />
                  {/* The thin art is 4 wide on a 5 pitch: repeat its last column to close the gap. */}
                  {thin && <svg x={4} width={1} height={FRAME_H} viewBox={`3 0 1 ${FRAME_H}`} dangerouslySetInnerHTML={{ __html: slotPiece(shadeFor(i, slots), thin) }} />}
                </g>
              ))}
              <g transform={`translate(${CAP_START + slots * pitch} 0)`} dangerouslySetInnerHTML={{ __html: capEnd }} />
            </g>
            {/* A nested svg clips its children; its width wipes the filled pips in or out from the right. */}
            <svg x={0} y={0} width={clip} height={FRAME_H} overflow="hidden" aria-hidden="true">
              {Array.from({ length: drawn }, (_, i) => (
                <image key={i} href={pip} x={CAP_START + i * pitch + 1} y={3} width={pipW} height={5} />
              ))}
            </svg>
          </>
        )}
      </svg>
      <span className="sub">{value}</span>
    </span>
  );
}
